package io.github.jesterportfolio.hearth.combat;

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.jesterportfolio.hearth.combat.CombatContent.*;

final class CombatGatheringTest {
    static final class Fixture {
        final CombatPlayersTest.Fixture f=new CombatPlayersTest.Fixture();final CompletableFuture<Void> saved=new CompletableFuture<>();final AtomicInteger starts=new AtomicInteger();boolean valid=true;
        final CombatPlayersTest.Body offline=new CombatPlayersTest.Body(f.access.forVerifiedServerLink(f.run,UUID.randomUUID()),f.p.position);
        final CombatContent stage=CombatAttemptTest.content(Pool.SHARED,1,LocationMode.START);
        final CombatAttempt path=new CombatAttempt(f.run,f.world,1,stage,List.of(new CombatAttempt.Entrant(f.p.ctx,f.p.token,f.p.position),new CombatAttempt.Entrant(f.q.ctx,f.q.token,f.q.position),new CombatAttempt.Entrant(offline.ctx,offline.token,offline.position)),new CombatAttemptTest.Actors(),f.owner,()->{},f.clock::get);
        final CombatContent.Path policy=new CombatContent.Path(stage,new FieldContent.Box(0,6,63,68,0,6),new Exit(new FieldContent.Point(20,64,20),42,5,0.5,List.of()));
        final CombatGathering gathering;final UUID request=UUID.randomUUID();
        Fixture(){f.p.health=0.75;f.q.position=new Pose(f.world,100,64,100,0,0);path.died(f.q.ctx,f.q.token,f.q.position);path.disconnect(offline.ctx,offline.token,offline.position);gathering=new CombatGathering(path,policy,List.of(f.p,f.q),()->saved,roster->{starts.incrementAndGet();path.finish(CombatAttempt.Outcome.RETIRED);return new CombatAttempt(f.run,f.world,1,CombatAttemptTest.content(Pool.SHARED,2,LocationMode.START),roster,new CombatAttemptTest.Actors(),f.owner,()->{},f.clock::get);},f.owner,()->{},()->valid&&f.generation.get()==1);}
        void pump(){f.pump();}void save(){saved.complete(null);pump();}void apply(){f.p.applying.complete(true);pump();f.q.applying.complete(true);pump();}
    }
    @Test void onlyOnlineSurvivorsGatherDeadOnlineReturnAndOfflineExcluded(){var x=new Fixture();var work=x.gathering.begin(x.request);assertSame(work,x.gathering.begin(x.request));x.pump();assertEquals(0,x.f.p.restores);assertFalse(x.gathering.barrier().toCompletableFuture().isDone());x.save();assertEquals(1,x.f.p.restores);assertEquals(0,x.f.q.restores);x.apply();var boss=work.toCompletableFuture().join();assertEquals(CombatGathering.Phase.STARTED,x.gathering.phase());assertEquals(2,boss.snapshot().difficultyPlayers());assertEquals(0,boss.snapshot().sharedUsed());assertTrue(boss.snapshot().members().stream().noneMatch(m->m.dead()||m.used()!=0));assertEquals(0.75,x.f.p.health);assertEquals(0.5,x.f.q.health);assertFalse(x.f.p.applyGuard.getAsBoolean());assertFalse(x.f.q.applyGuard.getAsBoolean());assertEquals(0,x.path.snapshot().sharedUsed());assertEquals(1,x.starts.get());assertThrows(IllegalStateException.class,()->boss.reconnect(x.offline.ctx,x.offline.token));Object fresh=new Object();boss.disconnect(x.f.p.ctx,x.f.p.token,x.f.p.position);assertEquals(x.policy.bossEntry().pose(x.f.world),boss.reconnect(x.f.p.ctx,fresh));}
    @Test void survivingPlayerOutsideBlocksWithoutFreezingOrSavingAndCanRetry(){var x=new Fixture();x.f.p.position=new Pose(x.f.world,99,64,99,0,0);assertTrue(x.gathering.begin(x.request).toCompletableFuture().isCompletedExceptionally());assertEquals(CombatGathering.Phase.IDLE,x.gathering.phase());x.f.p.position=new Pose(x.f.world,3,64,4,0,0);var work=x.gathering.begin(x.request);x.save();x.apply();assertFalse(work.toCompletableFuture().isCompletedExceptionally());}
    @Test void allDeadAndFailedPathCannotStartBoss(){for(boolean failed:List.of(false,true)){var x=new Fixture();if(failed)x.path.failedCondition(true);else x.path.died(x.f.p.ctx,x.f.p.token,x.f.p.position);assertTrue(x.gathering.begin(x.request).toCompletableFuture().isCompletedExceptionally());assertEquals(0,x.starts.get());}}
    @Test void saveFailureAndLeavingAreaDuringSaveNeverMoveOrStart(){for(boolean fail:List.of(false,true)){var x=new Fixture();var work=x.gathering.begin(x.request);x.pump();if(fail)x.saved.completeExceptionally(new IllegalStateException("DB_FAILED"));else{x.f.p.position=new Pose(x.f.world,100,64,100,0,0);x.saved.complete(null);}x.pump();assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertEquals(0,x.f.p.restores);assertEquals(0,x.starts.get());assertEquals(CombatGathering.Phase.HOLD,x.gathering.phase());}}
    @Test void rosterSessionGenerationAndCloseChangesRejectLateRestore(){for(int kind=0;kind<4;kind++){var x=new Fixture();var work=x.gathering.begin(x.request);x.save();if(kind==0)x.path.disconnect(x.f.q.ctx,x.f.q.token,x.f.q.position);else if(kind==1)x.f.p.live=false;else if(kind==2)x.f.generation.incrementAndGet();else x.gathering.close();assertFalse(x.f.p.applyGuard.getAsBoolean());x.apply();assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertEquals(0,x.starts.get());}}
    @Test void falseMoveAndUnsafeDestinationNeverSpawnBoss(){for(boolean unsafe:List.of(false,true)){var x=new Fixture();x.f.p.safe=!unsafe;var work=x.gathering.begin(x.request);x.save();if(!unsafe){x.f.p.applying.complete(false);x.pump();}assertTrue(work.toCompletableFuture().isCompletedExceptionally());assertEquals(0,x.starts.get());}}
    @Test void duplicateConflictAndPreviousActorGuardAreRejected(){var x=new Fixture();var work=x.gathering.begin(x.request);assertTrue(x.gathering.begin(UUID.randomUUID()).toCompletableFuture().isCompletedExceptionally());x.save();x.f.p.applying.complete(true);x.pump();assertFalse(x.f.p.applyGuard.getAsBoolean());assertTrue(x.f.q.applyGuard.getAsBoolean());x.f.q.applying.complete(true);x.pump();assertSame(work,x.gathering.begin(x.request));assertEquals(1,x.starts.get());}
    @Test void rejectedOwnerAndWrongRunDoNotStart(){var x=new Fixture();x.f.reject.set(true);assertTrue(x.gathering.begin(x.request).toCompletableFuture().isCompletedExceptionally());assertEquals(CombatGathering.Phase.HOLD,x.gathering.phase());var other=new Fixture();assertThrows(IllegalArgumentException.class,()->new CombatGathering(x.path,x.policy,List.of(other.f.p),()->x.saved,r->x.path,x.f.owner,()->{},()->true));}
    @Test void pathVictoryCanStillGatherAndCountersAreNotConsumed(){var x=new Fixture();x.path.victory();var work=x.gathering.begin(x.request);x.save();x.apply();assertFalse(work.toCompletableFuture().isCompletedExceptionally());assertEquals(CombatAttempt.Outcome.VICTORY,x.path.snapshot().outcome());assertEquals(0,x.path.snapshot().sharedUsed());}
}
